        case FLUX_ERR_INVALID_NUMBER_FORMAT: return "Verifique a formatação do número literal (números decimais devem ter dígitos antes e após o ponto)";
        case FLUX_ERR_BOOL_INVALID_LITERAL_CASING: return "Utilize 'True' ou 'False' com a primeira letra maiúscula";
